def numtopf(num, n=False):
    if not n:
        k = _sage_const_1 
        while (k+_sage_const_1 )**(k-_sage_const_1 ) < num:
            k += _sage_const_1 
        n = k
    digits = [(num//((n+_sage_const_1 )**j))%(n+_sage_const_1 ) for j in range(n-_sage_const_1 )]
    digits.reverse()
    pps = [[(i+_sage_const_1 +sum(digits[_sage_const_0 :j]))%(n+_sage_const_1 ) for j in range(n)] for i in range(n)]
    for pp in pps:
        wipp = sorted(pp)
        ispf = all([wipp[i] <= i+_sage_const_1  for i in range(n)])
        if _sage_const_0  not in wipp and ispf:
            return pp
    return "ERROR"

def pf_is_friendly(pf, graph):
    n = len(pf)
    out = [_sage_const_0 ]*n
    for i in range(n):
        fail = True
        for j in range(pf[i]-_sage_const_1 , n):
            left = max(_sage_const_0 , j-_sage_const_1 )
            right = min(j+_sage_const_1 , n-_sage_const_1 )
            if out[j] == _sage_const_0  and (out[left] == _sage_const_0  or out[left] in graph[i+_sage_const_1 ]) and (out[right] == _sage_const_0  or out[right] in graph[i+_sage_const_1 ]):
                out[j] = i+_sage_const_1 
                fail = False
                break
        if fail: 
            return False
    return True

def all_pfs_for_graph(graph):
    n = graph.order()
    pfs = [numtopf(i,n) for i in range((n+_sage_const_1 )**(n-_sage_const_1 ))]
    graph_pfs = []

    for pf in pfs:
        if pf_is_friendly(pf, graph):
            graph_pfs.append(pf)
    return graph_pfs

def all_paths_for_pf(pf):
    n = len(pf)
    labelings = list(Permutations(n))
    paths = []
    for label in labelings:
        graph = Graph([(label[i], label[i+_sage_const_1 ]) for i in range(n-_sage_const_1 )])
        if pf_is_friendly(pf, graph):
            paths.append(label)
    return paths

def outcome(pf):
    n = len(pf)
    outcome = [_sage_const_0 ]*n
    for i in range(n):
        for j in range(pf[i]-_sage_const_1 , n):
            if not outcome[j]:
                outcome[j] = i+_sage_const_1 
                break
    return outcome

