def displacement(pf):
    out = outcome(pf)
    tagged = sorted(list(zip(out, list(range(len(pf))))))
    return [tagged[i][_sage_const_1 ]+_sage_const_1  - pf[i] for i in range(len(pf))]

def preimage(perm):
    n = len(perm)
    options = [[] for i in range(n)]
    for i in range(n):
        for j in range(i, -_sage_const_1 , -_sage_const_1 ):
            if perm[j] <= perm[i]:
                options[perm[i]-_sage_const_1 ].append(j+_sage_const_1 )
            else:
                break
    prefs = list(cartesian_product(options))
    return prefs

def friendship_preimage(perm, graph):
    n = len(perm)
    options = [[] for i in range(n)]
    for i in range(n):
        for j in range(i, -_sage_const_1 , -_sage_const_1 ):
            if (perm[j] <= perm[i]):
                options[perm[i]-_sage_const_1 ].append(j+_sage_const_1 )
            elif (perm[j+_sage_const_1 ] <= perm[i]) and (perm[j+_sage_const_1 ] not in graph.neighbors(perm[i], closed=True)):
                options[perm[i]-_sage_const_1 ].append(j+_sage_const_1 )
            elif (j > _sage_const_0 ) and (perm[j-_sage_const_1 ] <= perm[i]) and (perm[j-_sage_const_1 ] not in graph.neighbors(perm[i], closed=True)):
                options[perm[i]-_sage_const_1 ].append(j+_sage_const_1 )
            else:
                break
    prefs = list(cartesian_product(options))
    return prefs

